import{z as d,x as A,o as t,c as p,q as l,j as r,D as o,d as E,s as i,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"部分冗余消除","description":"","frontmatter":{"title":"部分冗余消除","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/partial-redundancy-elim.md","filePath":"cs/partial-redundancy-elim.md","lastUpdated":1791063341000}'),B={name:"cs/partial-redundancy-elim.md"};function m(u,a,c,f,C,h){const n=A("Mermaid");return t(),p("div",null,[a[2]||(a[2]=l('<h1 id="部分冗余消除" tabindex="-1">部分冗余消除 <a class="header-anchor" href="#部分冗余消除" aria-label="Permalink to &quot;部分冗余消除&quot;">​</a></h1><div class="epigraph"><p>表达式在某些路径上已算过、某些没有：在缺少的路径上插入计算，使汇合点可用，再删除冗余。这是全局 CSE 与 LICM 的共同推广。</p><footer>—— 据 Morel and Renvoise, Global Optimization by Suppression of Partial Redundancies, 1979；Knoop, Rüthing and Steffen, Lazy Code Motion 整理</footer></div><p>上一课<a href="/cs/sroa">SROA</a>把更多表达式变成标量。缺口是<strong>部分冗余</strong>：<code>a+b</code> 在 <code>if</code> 的一枝算过，汇合后再算。PRE / lazy code motion：插入使变成完全可用，且尽量懒（不无故延长存活）。本课钉思想，不把全部数据流方程展开成作业。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>可用表达式要求<strong>所有</strong>前驱都可用才消除。部分：有的前驱有。插入：在没有的前驱出口补上。缺口是<strong>插入点选择</strong>，避免多余计算与非法投机（陷阱）。</p><p><span class="marginnote">「部分冗余」翻译成白话：同一条 <code>a+b</code>，在 if 的左枝已经算过、右枝还没算，汇合点之后又算一次。左枝那次是「完全冗余」可删，右枝到汇合这段是「部分」冗余——PRE 的办法就是在右枝也补一次计算，让汇合点两边都可用，再把汇合后那次删掉。</span></p><p>LCM（lazy code motion）把计算下移到尽可能晚，减寄存器压力。</p><p><span class="marginnote">「懒」在这里是褒义：计算不提前、拖到真正要用结果的前一刻。好处是结果值的存活期变短——类比网购宁可选晚一天送达，家里（寄存器）就不用腾地方早存货。寄存器紧张时，这个差别直接决定要不要溢出到栈。</span></p><h3 id="插入不是随便投机" tabindex="-1">插入不是随便投机 <a class="header-anchor" href="#插入不是随便投机" aria-label="Permalink to &quot;插入不是随便投机&quot;">​</a></h3><p>不能在不执行的路径上插入可能除零的运算，除非证明安全或原程序也会执行。与 LICM 的「必执行」同一类约束。</p><p><span class="marginnote">Morel–Renvoise 1979。Knoop–Rüthing–Steffen LCM。龙书 9.5 相关。LLVM 有 GVN-PRE。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据流：预期（anticipated）、可用、稍后。解方程，标记插入与删除。SSA 上可用 φ 与新名实现。</p>',13)),(t(),r(s,null,{default:o(()=>[i(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRED%5B%22%E9%83%A8%E5%88%86%E8%B7%AF%E5%BE%84%E5%B7%B2%E6%9C%89%20e%22%5D%20--%3E%20INS%5B%22%E7%BC%BA%E7%9A%84%E8%B7%AF%E5%BE%84%E6%8F%92%E5%85%A5%20e%22%5D%0A%20%20INS%20--%3E%20FULL%5B%22%E6%B1%87%E5%90%88%E5%90%8E%E5%AE%8C%E5%85%A8%E5%8F%AF%E7%94%A8%22%5D%0A%20%20FULL%20--%3E%20DEL%5B%22%E5%88%A0%E9%99%A4%E5%86%97%E4%BD%99%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 GVN：先编号再 PRE，识别代数等价。与循环：不变式外提是 PRE 的特例（环外插入）。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"代码体积：插入复制运算。临界边（从多后继到多前驱）要拆，否则插入点不唯一——CFG 变换。不要在 PRE 里移动 store；那是另一套（store PRE 更危险）。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},[E("「临界边」就是从多后继块跳到多前驱块的那条边：往它上面插计算，说不清该插进哪个后继、又会被哪些前驱共享。做法是凭空加一个空基本块把边一分为二，插入点就唯一了。数字实例："),e("code",null,"if"),E(" 两个出口汇到循环头，两条边都是临界边，拆开后各得一个空块放插入的 "),e("code",null,"a+b"),E("。")])],-1)),a[7]||(a[7]=e("p",null,"初学者容易以为 PRE 一定净赚：插入本身也是一次计算，若补出来的那条路径从来不执行，省下的只有汇合后那一次，代码体积却白涨——所以优化器要权衡插入的代价，且不能把可能除零的运算投机到未必执行的路径上。",-1)),(t(),r(s,null,{default:o(()=>[i(n,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E5%BE%AA%E7%8E%AF%E5%A4%B4%22%5D%20--%3E%20T%5B%22then%20%E5%9D%97%EF%BC%9A%E5%B7%B2%E7%AE%97%20a%2Bb%22%5D%0A%20%20H%20--%3E%20E%5B%22else%20%E5%9D%97%22%5D%0A%20%20T%20--%3E%20J%5B%22%E6%B1%87%E5%90%88%E5%9D%97%EF%BC%9A%E5%86%8D%E7%AE%97%E4%B8%80%E6%AC%A1%20a%2Bb%EF%BC%88%E5%86%97%E4%BD%99%EF%BC%89%22%5D%0A%20%20E%20--%3E%20J%0A%20%20T%20--%20%22%E4%B8%B4%E7%95%8C%E8%BE%B9%EF%BC%9A%E6%8B%86%E5%87%BA%E7%A9%BA%E5%9D%97%22%20--%3E%20S1%5B%22%E7%A9%BA%E5%9D%97%20S1%EF%BC%9A%E6%8F%92%E5%85%A5%20a%2Bb%22%5D%0A%20%20E%20--%20%22%E4%B8%B4%E7%95%8C%E8%BE%B9%EF%BC%9A%E6%8B%86%E5%87%BA%E7%A9%BA%E5%9D%97%22%20--%3E%20S2%5B%22%E7%A9%BA%E5%9D%97%20S2%EF%BC%9A%E6%8F%92%E5%85%A5%20a%2Bb%22%5D%0A%20%20S1%20--%3E%20J%0A%20%20S2%20--%3E%20J%0A%20%20J%20--%3E%20D%5B%22%E6%B1%87%E5%90%88%E5%90%8E%E7%9A%84%20a%2Bb%20%E8%A2%AB%E5%88%A0%E9%99%A4%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 LCM 最优性。后课默认：部分冗余可经插入变成 CSE。下一课值范围：另一格，服务消除比较与越界。</p><p>也不把 PRE 当死代码（那是删除无观察，不是移动计算）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PRE：插入补齐路径，消除部分冗余。</li><li>懒移动减寄存器压力；投机受陷阱约束。</li><li>LICM 是循环上的特例。</li><li>出处：Morel and Renvoise, 1979；Knoop et al. LCM；龙书。</li></ul>',5))])}const S=d(B,[["render",m]]);export{b as __pageData,S as default};
